SELECT CASE WHEN s.rating >= 3.8 THEN 'high' WHEN s.rating >= 2.4 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN p.category = 'Books' THEN p.price ELSE 0 END) AS books_price FROM products p INNER JOIN suppliers s ON s.id = p.supplier_id GROUP BY CASE WHEN s.rating >= 3.8 THEN 'high' WHEN s.rating >= 2.4 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN p.category = 'Books' THEN p.price ELSE 0 END) > 32;
